const SQL_QUERIES = {
  INSERT_PAYMENT: 'INSERT INTO payments (card_last_four, amount, status) VALUES ($1, $2, $3)',
  UPSERT_SUBSCRIPTION: `INSERT INTO subscriptions (user_id, tier, valid_until, features) VALUES ($1, $2, $3, $4) ON CONFLICT (user_id) DO UPDATE SET tier = $2, valid_until = $3, features = $4`,
  GET_SUBSCRIPTION_FEATURES: 'SELECT features, valid_until FROM subscriptions WHERE user_id = $1',
  GET_SUBSCRIPTION: 'SELECT * FROM subscriptions WHERE user_id = $1'
} as const;

export async function getUserSubscription(userId: string): Promise<Subscription | null> {
  const rows = await db.query(SQL_QUERIES.GET_SUBSCRIPTION, [userId]);
  if (rows.length === 0) return null;
  const row = rows[0];
  return {
    userId: row.user_id,
    tier: row.tier,
    validUntil: new Date(row.valid_until),
    features: JSON.parse(row.features)
  };
}

export async function hasFeatureAccess(userId: string, feature: string): Promise<boolean> {
  const subscription = await getUserSubscription(userId);
  if (!subscription) return false;
  if (subscription.validUntil < new Date()) return false;
  return subscription.features.includes(feature);
}

