function validatePaymentDetails(payment: PaymentDetails): boolean {
  const { cardNumber, expiryDate, cvv } = payment;
  const isValidCardNumber = cardNumber.length === 16;
  const isValidCvv = cvv.length === 3 || cvv.length === 4;
  const isValidExpiry = isValidExpiryDate(expiryDate);
  return isValidCardNumber && isValidCvv && isValidExpiry;
}

